import java.util.HashMap;
import java.util.Map;

Map result = new HashMap();
if (account == null) {
  return result;
}
Object employeeId = account.getAttribute("userId");
if (employeeId == null) {
  employeeId = account.getAttribute("employeeId");
}
if (employeeId != null) {
  // Attribute-based CorrelationConfig is primary for MNB-HR (userId).
  // Rule kept for academy traceability and Lesson 17–18 extensions.
  if (log != null && log.isDebugEnabled()) {
    log.debug("MNB-Rule-Correlation-EmployeeId saw userId=" + employeeId);
  }
}
return result;
